<?php require __DIR__.'/header.php'; ?><main id="main" class="container page-space narrow classified-submission"><div class="breadcrumbs"><a href="<?= e(url('classifieds')) ?>">Classifieds</a><span>›</span><span><?= e($title) ?></span></div><span class="eyebrow">COMMUNITY CLASSIFIEDS</span><h1><?= e($title) ?></h1><p class="muted">Classified listings are reviewed before publication and remain active for 30 days after approval.</p><nav class="submission-steps" aria-label="Listing form sections"><a href="#listing-details"><b>01</b>Listing details</a><a href="#listing-photos"><b>02</b>Photos & media</a><a href="#listing-contact"><b>03</b>Contact & submit</a></nav><?php if ($error): ?><p class="error" role="alert"><?= e($error) ?></p><?php endif ?><form method="post" enctype="multipart/form-data" class="panel form-stack"><?= csrf() ?><h2 class="form-section-title" id="listing-details">Listing details</h2><label>Title<input name="title" maxlength="200" required value="<?= e($item['title'] ?? '') ?>"></label><div class="form-grid"><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach ($classifiedCategories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= ($item['category_id'] ?? '')==$category['id'] ? 'selected' : '' ?>><?= e(localized($category,'name')) ?></option><?php endforeach ?></select></label><label>Language<select name="language"><?php foreach (['en'=>'English','si'=>'සිංහල','ta'=>'தமிழ்'] as $code=>$label): ?><option value="<?= e($code) ?>" <?= ($item['language'] ?? lang())===$code ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach ?></select></label></div><label>Description<textarea name="description" rows="7" maxlength="15000" required><?= e($item['description'] ?? '') ?></textarea></label><div class="form-grid"><label>Location<input name="location" maxlength="150" required value="<?= e($item['location'] ?? '') ?>"></label><label>Price (LKR, optional)<input type="number" name="price" min="0" max="9999999999.99" step="0.01" value="<?= e($item['price'] ?? '') ?>"></label></div><h2 class="form-section-title" id="listing-photos">Photos & media</h2><label>Photos (up to 8, 25 MB each)<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><?php if (!empty($item['images'])): ?><div class="photo-gallery"><?php foreach (json_decode($item['images'],true) ?: [] as $image): ?><img src="<?= e(media_url($image)) ?>" alt="Current listing photo"><?php endforeach ?></div><label class="check"><input type="checkbox" name="remove_images"> Remove existing photos when saving</label><?php endif ?><hr><h2 class="form-section-title" id="listing-contact">Public contact details</h2><p class="muted">These details will appear publicly on your classified listing.</p><label>Contact name<input name="contact_name" maxlength="150" required value="<?= e($item['contact_name'] ?? $user['name']) ?>"></label><div class="form-grid"><label>Email<input name="contact_email" type="email" required value="<?= e($item['contact_email'] ?? $user['email']) ?>"></label><label>Phone<input name="contact_phone" type="tel" maxlength="40" required value="<?= e($item['contact_phone'] ?? '') ?>"></label></div><label class="check"><input type="checkbox" name="premium_requested" <?= !empty($item['premium_requested']) ? 'checked' : '' ?>> Request premium placement</label><small class="muted">The team will arrange pricing and payment separately. Submitting this form does not charge you.</small><button class="button">Submit for review →</button></form></main><?php require __DIR__.'/footer.php'; ?>
